// Exports the real English project data for the restyle mockups.
//   node prototypes/restyle/export-data.js
// Writes prototypes/restyle/data/projects.js -> window.__PROJECTS__ (slug -> project)
const fs = require('node:fs');
const path = require('node:path');
const root = path.resolve(__dirname, '..', '..');
const { projects } = require(path.join(root, 'content', 'projects'));

const out = {};
for (const p of projects) {
  out[p.slug] = {
    slug: p.slug,
    tags: p.tags,
    coverImage: p.coverImage,
    title: p.head.en.title,
    header: p.header.en,
    sections: p.sections.en,
  };
}
const file = path.join(__dirname, 'data', 'projects.js');
fs.writeFileSync(file, `// Generated by export-data.js from content/projects. Do not edit.\nwindow.__PROJECTS__ = ${JSON.stringify(out, null, 1)};\n`);
console.log('wrote', path.relative(root, file), Object.keys(out).join(', '));
